"""Read-only, stdlib-only hipprof/Chrome survey accounting; see ACCOUNTING_API.md.

Adapted from matrix-family/r2 and index-family/r2 trace_accounting.py:
producer linkage precedes ROI membership; no timing-only GPU attribution.
"""
from __future__ import annotations

import argparse
from bisect import bisect_left, bisect_right
from collections import defaultdict
from decimal import Decimal
import gzip
import hashlib
import json
from pathlib import Path
import re
import statistics
import sys

LAUNCHES = frozenset({
    "hipModuleLaunchKernel", "hipExtModuleLaunchKernel", "hipLaunchKernel",
    "hipExtLaunchKernel", "hipHccModuleLaunchKernel", "hipLaunchCooperativeKernel",
    "hipModuleLaunchCooperativeKernel", "hipLaunchCooperativeKernelMultiDevice",
    "hipGraphLaunch", "cudaLaunchKernel", "cudaLaunchKernelExC",
    "cudaLaunchCooperativeKernel", "cudaGraphLaunch", "cuLaunchKernel",
    "cuLaunchCooperativeKernel",
})
MULTI_LAUNCH = frozenset({"hipGraphLaunch", "cudaGraphLaunch",
                         "hipLaunchCooperativeKernelMultiDevice"})
TRACK = re.compile(
    r"^\[\d+\] (?P<kind>Compute on Device \d+|Memory Copy on Device \d+|"
    r"Runtime API|HSA API|LIBC API|Opencl API|OMP Runtime API|MPI API|"
    r"Markers and Ranges)(?: IP:(?P<host>\S+) pid:(?P<pid>\d+))?$"
)
DEFAULT_ROI_REGEX = r"SURVEY\|(?P<caseid>[^|]+)\|(?P<route>fg|das)\|ROI\|(?P<rep>\d+)"


class Invalid(ValueError):
    """Unsupported, ambiguous, or unprovable accounting evidence."""


def _integer(value, field):
    if type(value) is int and value >= 0:
        return value
    if isinstance(value, str) and re.fullmatch(r"[0-9]+", value):
        return int(value)
    raise Invalid(f"{field}: expected nonnegative integer, not float/bool")


def _id(value):
    if isinstance(value, bool) or not isinstance(value, (int, str)) or str(value) == "":
        raise Invalid("missing/invalid correlation identifier")
    return str(value)


def _number(value):
    if isinstance(value, bool) or not isinstance(value, (int, Decimal, str)):
        raise Invalid("timestamp must be finite JSON number")
    try:
        result = Decimal(value)
    except Exception as exc:
        raise Invalid("invalid timestamp") from exc
    if not result.is_finite() or result < 0:
        raise Invalid("timestamp must be finite and nonnegative")
    return result


def _nodup(pairs):
    out = {}
    for key, value in pairs:
        if key in out:
            raise Invalid("duplicate JSON key: " + key)
        out[key] = value
    return out


def _read(path):
    data = path.read_bytes()
    decoded = gzip.decompress(data) if path.name.endswith(".gz") else data
    doc = json.loads(decoded.decode("utf-8-sig"), parse_float=Decimal,
                     object_pairs_hook=_nodup,
                     parse_constant=lambda x: (_ for _ in ()).throw(Invalid("nonfinite JSON: " + x)))
    return doc, {"path": str(path), "bytes": len(data),
                 "sha256": hashlib.sha256(data).hexdigest()}


def _interval(raw, hip):
    args = raw.get("args", {})
    if hip:
        lo = _integer(args.get("BeginNs"), "BeginNs")
        hi = _integer(args.get("EndNs"), "EndNs")
        if "DurationNs" in args and _integer(args["DurationNs"], "DurationNs") != hi - lo:
            raise Invalid("DurationNs disagrees with EndNs-BeginNs")
        return Decimal(lo), Decimal(hi)
    lo = _number(raw.get("ts")) * 1000  # Chrome ts/dur are microseconds.
    return lo, lo + _number(raw.get("dur")) * 1000


def _contains(outer, inner):
    return outer["lo"] <= inner["lo"] and inner["hi"] <= outer["hi"]


def _overlaps(a, b):
    return a["lo"] < b["hi"] and b["lo"] < a["hi"]


def _union(events):
    end, total = None, Decimal(0)
    for lo, hi in sorted((e["lo"], e["hi"]) for e in events):
        if end is None or lo > end:
            total += hi - lo
        elif hi > end:
            total += hi - end
        end = hi if end is None else max(end, hi)
    return total


def _api_name(event):
    return event["name"].split("(", 1)[0].strip()


def _memory_api(event):
    return _api_name(event).startswith(("hipMemcpy", "hipMemset", "cudaMemcpy",
                                          "cudaMemset", "cuMemcpy", "cuMemset"))


def _event_ref(e):
    return {"event_index": e["index"], "name": e["name"], "kind": e["kind"],
            "producer_pid": e["pid"], "trace_track": e["track"],
            "begin_ns": str(e["lo"]), "end_ns": str(e["hi"])}


def _normalize(doc):
    raw = doc.get("traceEvents") if isinstance(doc, dict) else doc
    if not isinstance(raw, list) or not raw:
        raise Invalid("expected nonempty Chrome traceEvents array")
    if len(raw) > 8_000_000:
        raise Invalid("event limit exceeded; refusing partial accounting")
    tracks, labels, host_metadata = {}, {}, set()
    for e in raw:
        if not isinstance(e, dict):
            raise Invalid("non-object trace event")
        if e.get("ph") == "M" and e.get("name") == "process_name":
            track, label = _id(e.get("pid")), e.get("args", {}).get("name", "")
            if track in labels and labels[track] != label:
                raise Invalid("conflicting process_name for track " + track)
            labels[track] = label
            m = TRACK.fullmatch(label)
            if m:
                tracks[track] = m.groupdict()
        if e.get("ph") == "M" and e.get("name") in {"hostname", "host_name"}:
            host_metadata.add(str(e.get("args", {}).get("name", "")))
    if isinstance(doc, dict):
        for field in ("hostname", "hostName", "host"):
            if doc.get(field):
                host_metadata.add(str(doc[field]))
    hip = bool(tracks)
    events, stacks = [], defaultdict(list)
    for i, original in enumerate(raw):
        e = original
        phase = e.get("ph")
        if phase in {"B", "E"}:
            # NVTX begin/end ranges only; never reconstruct GPU/API activities.
            key = (_id(e.get("pid")), _id(e.get("tid")))
            if phase == "B":
                stacks[key].append((i, e))
                continue
            if not stacks[key]:
                raise Invalid("unpaired B/E range end")
            start_index, start = stacks[key].pop()
            e = dict(start, ph="X")
            if hip:
                e["args"] = dict(start.get("args", {}))
                e["args"]["EndNs"] = original.get("args", {}).get("EndNs", original.get("args", {}).get("BeginNs"))
            else:
                e["dur"] = _number(original.get("ts")) - _number(start.get("ts"))
            i = start_index
        elif phase != "X":
            if phase not in {"M", "s", "t", "f", "i", "I", "C", "R", "N", "O", "D"}:
                raise Invalid("unsupported trace phase: " + str(phase))
            continue
        args = e.get("args", {})
        if not isinstance(args, dict):
            raise Invalid("event args is not object")
        track = _id(e.get("pid"))
        info = tracks.get(track)
        cat = e.get("cat", "")
        name = e.get("name", "")
        if hip and info:
            label = info["kind"]
            kind = ("kernel" if label.startswith("Compute") else
                    "memory" if label.startswith("Memory Copy") else
                    "marker" if label == "Markers and Ranges" else "api")
            pid = _integer(args.get("pid", info.get("pid")), "producer pid")
            if info.get("pid") and pid != int(info["pid"]):
                raise Invalid("track PID disagrees with activity producer PID")
            if "procId" in args and _integer(args["procId"], "procId") != pid:
                raise Invalid("procId disagrees with activity producer PID")
            if kind in {"kernel", "memory"} and "devId" in args:
                if _integer(args["devId"], "devId") != int(label.rsplit(" ", 1)[1]):
                    raise Invalid("devId disagrees with device track")
            host = info.get("host")
        else:
            kind = {"kernel": "kernel", "gpu_memcpy": "memory", "gpu_memset": "memory",
                    "cpu_op": "cpu", "cuda_runtime": "api", "hip_runtime": "api",
                    "cuda_driver": "api", "user_annotation": "marker", "nvtx": "marker",
                    "NVTX": "marker"}.get(cat)
            if kind is None:
                # Unknown host diagnostics may be ignored; unknown GPU work may not.
                if cat in {"HIPOPS", "HIPCOPY", "HIP", "gpu_kernel"} or name.startswith("SURVEY|"):
                    raise Invalid("unclassified activity/ROI track")
                continue
            if hip and kind in {"kernel", "memory"}:
                raise Invalid("device activity on unclassified hipprof track")
            pid = None if kind in {"kernel", "memory"} else _integer(e.get("pid"), "host pid")
            host = None
        lo, hi = _interval(e, hip)
        if hi < lo:
            raise Invalid("negative activity duration")
        tid = _id(args.get("tid", e.get("tid"))) if hip else _id(e.get("tid"))
        if hip and re.fullmatch(r"Thread[0-9]+", tid):
            tid = tid[len("Thread"):]
        # Marker args.tid, when present, is the real producer thread.
        events.append(dict(index=i, name=name, kind=kind, pid=pid, host=host,
                           track=track, tid=tid, lo=lo, hi=hi, args=args,
                           device=args.get("devId", args.get("device"))))
    if any(stacks.values()):
        raise Invalid("unclosed B/E ranges")
    return events, tracks, host_metadata, hip


def _empty_case():
    return dict(status="error", roi_count=0, valid_roi_count=0, kernel_us=None,
                memory_us=None, device_union_us=None, rois=[], errors=[])


def analyze(raw_dir: Path, worker_path: Path, *, prefix="SURVEY", expected_rois=5,
            roi_regex=None, host_aliases=None, roi_source="worker") -> dict:
    """Parse raw files without writing. Errors withhold medians; see the API document.

    host_aliases is a caller-verified mapping hostname -> list of trace IP/host tokens.
    roi_source='worker' uses trusted epoch-ns receipt spans (default).
    roi_source='nvtx' requires trace markers and never falls back to receipt spans.
    """
    result = dict(schema="survey-accounting/v1", status="error", unit="us", cases={},
                  errors=[], warnings=[], inputs=[], producer={},
                  capture_completeness="unknown; linkage is not proof of lossless capture")
    try:
        if type(expected_rois) is not int or expected_rois <= 0:
            raise Invalid("expected_rois must be positive integer")
        if roi_source not in {"nvtx", "worker"}:
            raise Invalid("roi_source must be nvtx or worker")
        worker, provenance = _read(Path(worker_path))
        result["inputs"].append(provenance)
        if not isinstance(worker, dict):
            raise Invalid("worker receipt must be object")
        identity = worker.get("identity", {})
        if not isinstance(identity, dict):
            raise Invalid("worker.identity must be object")
        pid = _integer(identity.get("pid"), "worker.identity.pid")
        host = identity.get("host", identity.get("hostname"))
        if not isinstance(host, str) or not host:
            raise Invalid("missing worker.identity.host")
        route = worker.get("route")
        if route not in {"fg", "das"}:
            raise Invalid("worker.route must be fg or das")
        records = worker.get("records")
        if not isinstance(records, list) or not records:
            raise Invalid("worker.records must be nonempty list with unique id")
        by_id = {}
        for record in records:
            cid = record.get("id") if isinstance(record, dict) else None
            if not isinstance(cid, str) or not cid or cid in by_id:
                raise Invalid("missing or duplicate worker record id")
            by_id[cid] = record
            result["cases"][cid] = _empty_case()
        result["producer"] = {"worker_pid": pid, "worker_host": host, "route": route}
        if worker.get("status") not in {"ok", "partial"}:
            result["errors"].append("worker receipt is not completed (expected ok or partial)")
        elif worker.get("status") == "partial":
            result["warnings"].append("partial worker receipt: each case is assessed independently")
        candidates = []
        root = Path(raw_dir)
        paths = [root] if root.is_file() else sorted(p for p in root.rglob("*")
                    if p.is_file() and (p.suffix == ".json" or p.name.endswith(".json.gz")))
        for path in paths:
            if path.resolve() == Path(worker_path).resolve():
                continue
            try:
                doc, source = _read(path)
            except (ValueError, OSError, UnicodeError) as exc:
                raise Invalid(f"unreadable JSON candidate {path.name}: {exc}") from exc
            if (isinstance(doc, dict) and isinstance(doc.get("traceEvents"), list)) or isinstance(doc, list):
                candidates.append((doc, source))
        if len(candidates) != 1:
            raise Invalid(f"expected exactly one trace JSON, found {len(candidates)}; select a raw directory/file explicitly")
        doc, source = candidates[0]
        result["inputs"].append(source)
        events, tracks, trace_hosts, hip = _normalize(doc)
        result["dialect"] = "hipprof-type0" if hip else "chrome"
        result["roi_source"] = roi_source
        result["event_count"] = len(events)
        allowed_hosts = {host}
        aliases = (host_aliases or {}).get(host, [])
        if isinstance(aliases, str):
            raise Invalid("host_aliases values must be lists, not strings")
        allowed_hosts.update(aliases)
        for field in ("host_ips", "host_aliases"):
            extra = identity.get(field, [])
            if not isinstance(extra, list):
                raise Invalid(f"identity.{field} must be list")
            allowed_hosts.update(extra)
        if hip:
            relevant = [t for t in tracks.values() if t.get("pid") == str(pid)]
            if not relevant or any(not t.get("host") for t in relevant):
                result["errors"].append("missing trace PID/host metadata for worker")
            trace_hosts.update(t["host"] for t in relevant if t.get("host"))
        if not trace_hosts or not trace_hosts.issubset(allowed_hosts):
            result["errors"].append("trace host missing or not bound to worker host; supply verified identity.host_ips/host_aliases")
        result["producer"]["trace_hosts"] = sorted(trace_hosts)
        host_events = [e for e in events if e["pid"] == pid and e["kind"] in {"api", "cpu", "marker"}]
        if not host_events:
            result["errors"].append("no host activities for worker PID")
        pattern = re.compile(roi_regex or (re.escape(prefix) + DEFAULT_ROI_REGEX[len("SURVEY"):]))
        rois = []
        if roi_source == "nvtx":
            for e in events:
                m = pattern.fullmatch(e["name"]) if e["kind"] == "marker" else None
                if not m:
                    continue
                fields = m.groupdict()
                cid = fields.get("caseid")
                if cid not in by_id:
                    result["errors"].append("unknown ROI case: " + str(cid))
                    continue
                case = result["cases"][cid]
                if e["pid"] != pid or (fields.get("route") or route) != route:
                    case["errors"].append("ROI producer PID or route differs from worker")
                    continue
                rep = _integer(fields.get("rep", "0"), "ROI rep")
                rois.append(dict(e, caseid=cid, rep=rep))
        else:
            if not hip:
                raise Invalid("worker ROI requires explicit hipprof BeginNs/EndNs epoch clock")
            for cid, record in by_id.items():
                spans = record.get("roi", [])
                if not isinstance(spans, list):
                    result["cases"][cid]["errors"].append("record.roi must be a list")
                    continue
                for r in spans:
                    try:
                        if not isinstance(r, dict):
                            raise Invalid("worker ROI must be object")
                        rois.append(dict(index=None, name="worker epoch ROI", kind="marker", pid=pid,
                            track=None, tid=_id(r["tid"]) if "tid" in r else None,
                            lo=Decimal(_integer(r.get("start_epoch_ns"), "ROI start")),
                            hi=Decimal(_integer(r.get("end_epoch_ns"), "ROI end")),
                            caseid=cid, rep=_integer(r.get("rep"), "ROI rep")))
                    except (ValueError, TypeError) as exc:
                        result["cases"][cid]["errors"].append(str(exc))
            result["warnings"].append("worker epoch spans: no NVTX validation or inferred clock offset")
        for roi in rois:
            roi["errors"] = []
            roi["devices"] = []
            roi["apis"] = []
            if roi["hi"] <= roi["lo"]:
                roi["errors"].append("empty/reversed ROI")
        ordered = sorted((r for r in rois if r["hi"] > r["lo"]), key=lambda r: r["lo"])
        for previous, current in zip(ordered, ordered[1:]):
            if _overlaps(previous, current):
                raise Invalid("ROI overlaps another case/repetition")
        starts = [r["lo"] for r in ordered]

        def containing(event):
            i = bisect_right(starts, event["lo"]) - 1
            if i >= 0 and _contains(ordered[i], event):
                return [ordered[i]]
            return []

        def intersecting(event):
            left = max(0, bisect_right(starts, event["lo"]) - 1)
            right = bisect_left(starts, event["hi"])
            return [r for r in ordered[left:right] if _overlaps(r, event)]

        def runtime(e):
            return e["kind"] == "api" and _api_name(e).startswith(("hip", "__hip", "cuda", "cu"))

        apis = [e for e in host_events if runtime(e)]
        cpus = [e for e in host_events if e["kind"] == "cpu"]
        api_keys, cpu_keys = defaultdict(list), defaultdict(list)
        for e in (apis if hip else [x for x in events if runtime(x)]):
            if hip and "index" in e["args"]:
                api_keys[("index", str(_integer(e["args"]["index"], "producer index")))].append(e)
            for field in ("correlation", "Correlation ID"):
                if field in e["args"]:
                    api_keys[("correlation", _id(e["args"][field]))].append(e)
        for e in [x for x in events if x["kind"] == "cpu"]:
            if "External id" in e["args"]:
                cpu_keys[_id(e["args"]["External id"])].append(e)
        # Cache ownership: CPU events can be nested but a producer is assigned only
        # if its own full interval/thread is within one ROI. No GPU timing matching.
        owner_rois = {}
        for owner in apis + cpus:
            owners = [r for r in containing(owner) if
                      r["tid"] is None or r["tid"] == owner["tid"]]
            owner_rois[owner["index"]] = owners
            for r in intersecting(owner) if owner["kind"] == "api" else []:
                if not _contains(r, owner):
                    # Only a final blocking HIP wait in a trusted worker ROI can
                    # straddle the right host boundary. All launches, memory
                    # producers and device events retain exact full containment.
                    final_wait = (
                        hip and roi_source == "worker"
                        and _api_name(owner) in {"hipDeviceSynchronize", "hipStreamSynchronize"}
                        and r["tid"] is not None and r["tid"] == owner["tid"]
                        and r["lo"] <= owner["lo"] < r["hi"] < owner["hi"]
                    )
                    if final_wait:
                        r.setdefault("completion_sync_events", []).append({
                            **_event_ref(owner),
                            "host_end_overhang_ns": str(owner["hi"] - r["hi"]),
                            "policy": "completion-only blocking wait; not a producer; device and producer bounds unchanged",
                        })
                    else:
                        r["errors"].append("host activity crosses ROI boundary: " + str(owner["index"]))
            if owner["kind"] == "api":
                for r in owners:
                    r["apis"].append(owner)
        linked = defaultdict(list)
        for gpu in (e for e in events if e["kind"] in {"kernel", "memory"}):
            if hip and gpu["pid"] != pid:
                continue
            args, paths_to_owner = gpu["args"], []
            if hip:
                if "index" in args:
                    paths_to_owner.append(api_keys.get(("index", str(_integer(args["index"], "producer index"))), []))
                else:
                    paths_to_owner.append([])
            for field in ("correlation", "Correlation ID"):
                if field in args and (hip or apis or "External id" not in args):
                    paths_to_owner.append(api_keys.get(("correlation", _id(args[field])), []))
            cpu_owner = None
            if "External id" in args:
                choices = cpu_keys.get(_id(args["External id"]), [])
                if len(choices) != 1:
                    result["errors"].append(f"GPU event {gpu['index']} lacks unique External id CPU owner")
                    continue
                cpu_owner = choices[0]
                paths_to_owner.append([cpu_owner])
            if not paths_to_owner or any(len(choices) != 1 for choices in paths_to_owner):
                result["errors"].append(f"GPU event {gpu['index']} lacks unique producer linkage")
                continue
            owners = [choices[0] for choices in paths_to_owner]
            if all(o["pid"] != pid for o in owners):
                continue
            if any(o["pid"] != pid for o in owners):
                result["errors"].append("conflicting producer PIDs for GPU event " + str(gpu["index"]))
                continue
            runtime_owners = [o for o in owners if o["kind"] == "api"]
            if len({o["index"] for o in runtime_owners}) > 1:
                result["errors"].append("conflicting runtime correlations for GPU event " + str(gpu["index"]))
                continue
            owner = runtime_owners[0] if runtime_owners else cpu_owner
            if runtime_owners and cpu_owner and (not _contains(cpu_owner, owner) or cpu_owner["tid"] != owner["tid"]):
                result["errors"].append("External id CPU owner conflicts with launch API for GPU event " + str(gpu["index"]))
                continue
            if owner["lo"] > gpu["lo"]:
                result["errors"].append("device activity precedes producer launch " + str(gpu["index"]))
                continue
            if owner["kind"] == "api":
                name = _api_name(owner)
                if gpu["kind"] == "kernel" and name not in LAUNCHES and not _memory_api(owner):
                    result["errors"].append("kernel linked to unrecognized launch API " + name)
                    continue
                if gpu["kind"] == "memory" and not (
                        _memory_api(owner) or name in MULTI_LAUNCH or
                        name.startswith(("hipMalloc", "hipHostMalloc", "hipFree", "hipMem",
                                         "cudaMalloc", "cudaFree", "cudaMem", "cuMem"))):
                    result["errors"].append("memory linked to unrecognized producer API " + name)
                    continue
            members = owner_rois.get(owner["index"], [])
            if cpu_owner and members != owner_rois.get(cpu_owner["index"], []):
                result["errors"].append("CPU owner and runtime API disagree on ROI membership")
                continue
            linked[owner["index"]].append(gpu)
            gpu["owner"] = owner
            gpu["cpu_owner"] = cpu_owner
            for r in members:
                if not _contains(r, gpu):
                    r["errors"].append("linked device event crosses ROI boundary: " + str(gpu["index"]))
                r["devices"].append(gpu)
            # A correlated launch outside a ROI must not leak work into it.
            for r in intersecting(gpu):
                if not any(r is m for m in members):
                    r["errors"].append("device work from producer outside ROI overlaps ROI: " + str(gpu["index"]))
        for roi in rois:
            for api in roi["apis"]:
                name, outputs = _api_name(api), linked.get(api["index"], [])
                if name in LAUNCHES:
                    ks = [e for e in outputs if e["kind"] == "kernel"]
                    if not ks or (name not in MULTI_LAUNCH and len(ks) != 1):
                        roi["errors"].append("launch/kernel count linkage incomplete: " + str(api["index"]))
                elif "Launch" in name:
                    roi["errors"].append("unclassified launch-like API: " + name)
                if _memory_api(api) and not outputs:
                    roi["errors"].append("memory API without linked device activity; zero-byte/host-only not proven")
            devices = roi["devices"]
            kernels = [e for e in devices if e["kind"] == "kernel"]
            memory = [e for e in devices if e["kind"] == "memory"]
            explicit = by_id[roi["caseid"]].get("metadata_only") is True
            if explicit and devices:
                roi["errors"].append("metadata_only contradicts device activity")
            if not kernels:
                # Absence alone is not evidence. A synchronized runtime span or
                # explicit metadata-only receipt is required for a legitimate zero.
                sync = any(_api_name(a) in {"hipDeviceSynchronize", "hipStreamSynchronize",
                           "hipEventSynchronize", "cudaDeviceSynchronize", "cudaStreamSynchronize",
                           "cudaEventSynchronize"} for a in roi["apis"])
                if not sync and not explicit:
                    roi["errors"].append("zero kernel is unverified: need synchronization API or metadata_only receipt")
            sample = {"rep": roi["rep"], "event_index": roi["index"], "route": route,
                "begin_ns": str(roi["lo"]), "end_ns": str(roi["hi"]),
                "kernel_count": len(kernels), "memory_count": len(memory),
                "api_count": len(roi["apis"]), "errors": list(dict.fromkeys(roi["errors"])),
                "completion_sync_events": roi.get("completion_sync_events", []),
                "kernel_us": float(sum((e["hi"] - e["lo"] for e in kernels), Decimal(0)) / 1000),
                "memory_us": float(_union(memory) / 1000),
                "device_union_us": float(_union(devices) / 1000),
                "links": [{"device": _event_ref(e), "producer": _event_ref(e["owner"]),
                           "cpu_owner": _event_ref(e["cpu_owner"]) if e["cpu_owner"] else None,
                           "producer_index": e["args"].get("index"),
                           "external_id": e["args"].get("External id")} for e in devices]}
            sample["status"] = "error" if sample["errors"] or result["errors"] else "ok"
            if sample["status"] != "ok":
                for field in ("kernel_us", "memory_us", "device_union_us"):
                    sample[field] = None
            result["cases"][roi["caseid"]]["rois"].append(sample)
        for cid, case in result["cases"].items():
            rec = by_id[cid]
            numerical_diagnostic = (
                rec.get("correct") is False
                and rec.get("performance_only_numerical_failure") is True
                and rec.get("historical_numerical_failure_allowed") is True
                and rec.get("semantic_checks_passed") is True
                and isinstance(rec.get("numerical_failures"), list)
                and bool(rec["numerical_failures"])
            )
            if rec.get("status") != "ok":
                case["errors"].append("worker record lacks valid semantics or authorized historical numerical diagnostic")
            case["numerical_correct"] = rec.get("correct")
            case["performance_only_numerical_failure"] = numerical_diagnostic
            samples = sorted(case["rois"], key=lambda s: s["rep"])
            case["rois"] = samples
            case["roi_count"] = len(samples)
            case["valid_roi_count"] = sum(s["status"] == "ok" for s in samples)
            if len(samples) != expected_rois or {s["rep"] for s in samples} != set(range(expected_rois)):
                case["errors"].append(f"requires exactly {expected_rois} ROI reps 0..{expected_rois - 1}")
            if any(s["status"] != "ok" for s in samples):
                case["errors"].append("one or more ROIs failed; no subset median")
            case["errors"].extend(result["errors"])
            case["errors"] = list(dict.fromkeys(case["errors"]))
            if not case["errors"]:
                case["status"] = "ok"
                for field in ("kernel_us", "memory_us", "device_union_us"):
                    case[field] = statistics.median(s[field] for s in samples)
        valid = sum(c["status"] == "ok" for c in result["cases"].values())
        result["status"] = ("ok" if valid == len(result["cases"]) and not result["errors"] else
                            "partial" if valid and not result["errors"] else "error")
    except (ValueError, TypeError, OSError, UnicodeError, KeyError, EOFError, AttributeError, re.error) as exc:
        result["errors"].append(str(exc))
        for case in result["cases"].values():
            case["status"] = "error"
            case["errors"].append(str(exc))
            for field in ("kernel_us", "memory_us", "device_union_us"):
                case[field] = None
    return result


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("raw_dir", type=Path)
    parser.add_argument("worker_path", type=Path)
    parser.add_argument("--prefix", default="SURVEY")
    parser.add_argument("--expected-rois", type=int, default=5)
    parser.add_argument("--roi-regex")
    parser.add_argument("--roi-source", choices=("nvtx", "worker"), default="worker")
    parser.add_argument("--host-alias", action="append", default=[], metavar="HOST=IP")
    args = parser.parse_args(argv)
    aliases = defaultdict(list)
    for value in args.host_alias:
        if "=" not in value:
            parser.error("--host-alias must be HOST=IP")
        host, alias = value.split("=", 1)
        aliases[host].append(alias)
    report = analyze(args.raw_dir, args.worker_path, prefix=args.prefix,
                     expected_rois=args.expected_rois, roi_regex=args.roi_regex,
                     roi_source=args.roi_source, host_aliases=aliases)
    print(json.dumps(report, ensure_ascii=True, allow_nan=False))
    return 0 if report["status"] in {"ok", "partial"} else 2


if __name__ == "__main__":
    raise SystemExit(main())
